from pathlib import Path

import pytest
from pdfminer.pdfparser import PDFSyntaxError
from pdfplumber.page import Page
from pdfplumber.utils.exceptions import MalformedPDFException, PdfminerException

from app.ingestion.errors import DocumentReadError, EmptyDocumentError, IngestionError
from app.ingestion.loaders import load_pdf

# Generated by tests/fixtures/ingestion/make_pdf_fixtures.py.
FIXTURES = Path(__file__).parents[1] / "fixtures" / "ingestion"
SAMPLE = FIXTURES / "ornek_yonerge.pdf"  # page 1 text, page 2 blank, page 3 text
BLANK = FIXTURES / "bos.pdf"  # two pages, no text
ENCRYPTED = FIXTURES / "sifreli.pdf"  # needs a password


def test_each_page_with_text_is_one_segment_with_its_page_number() -> None:
    doc = load_pdf(SAMPLE)

    assert doc.file_type == "pdf"
    assert doc.source == SAMPLE
    assert doc.encoding is None
    assert [segment.page for segment in doc.segments] == [1, 3]
    assert doc.segments[0].text.startswith("Örnek Staj Yönergesi\nMadde 1 - Öğrenciler")
    assert doc.segments[1].text.startswith("Madde 2 - İŞ GÜVENLİĞİ")


def test_turkish_letters_survive_extraction() -> None:
    # Also proves the fixture really contains these letters (Helvetica could not draw them).
    text = load_pdf(SAMPLE).text

    for letter in "ıİşŞğĞüÜöÖçÇ":
        assert letter in text
    assert "Cumartesi günü iş günü sayılır." in text


def test_page_without_text_is_skipped_with_a_warning() -> None:
    doc = load_pdf(SAMPLE)

    assert doc.warnings == ("page 2: no text (possibly scanned)",)


def test_pdf_without_any_text_raises() -> None:
    with pytest.raises(EmptyDocumentError) as exc_info:
        load_pdf(BLANK)

    assert exc_info.value.source == BLANK
    assert "bos.pdf" in str(exc_info.value)


@pytest.mark.parametrize(
    "data",
    [b"", b"bu bir PDF degil", b"%PDF-1.4\n1 0 obj\n<<"],
    ids=["empty", "not-a-pdf", "truncated"],
)
def test_corrupt_file_raises_read_error(tmp_path: Path, data: bytes) -> None:
    # pdfplumber wraps these in PdfminerException while opening the file.
    path = tmp_path / "Bozuk.pdf"
    path.write_bytes(data)

    with pytest.raises(DocumentReadError) as exc_info:
        load_pdf(path)

    assert isinstance(exc_info.value.__cause__, PdfminerException)
    assert "Bozuk.pdf" in str(exc_info.value)


@pytest.mark.parametrize(
    "error",
    [PDFSyntaxError("bad content stream"), MalformedPDFException("bad page")],
    ids=["unwrapped-pdfminer", "pdfplumber-malformed"],
)
def test_error_while_reading_a_page_raises_read_error(
    monkeypatch: pytest.MonkeyPatch, error: Exception
) -> None:
    def broken_extract_text(self: Page, **kwargs: object) -> str:
        raise error

    monkeypatch.setattr(Page, "extract_text", broken_extract_text)

    with pytest.raises(DocumentReadError) as exc_info:
        load_pdf(SAMPLE)

    assert exc_info.value.__cause__ is error


def test_encrypted_pdf_raises_read_error() -> None:
    with pytest.raises(DocumentReadError) as exc_info:
        load_pdf(ENCRYPTED)

    assert "PDFPasswordIncorrect" in str(exc_info.value)


def test_pdf_loader_errors_share_the_ingestion_base_class(tmp_path: Path) -> None:
    path = tmp_path / "Bozuk.pdf"
    path.write_bytes(b"")

    with pytest.raises(IngestionError):
        load_pdf(path)
